solution.solution.cpp:
#include <sstream>
#include <string>
#include <vector>

std::vector<std::string> wrapText(const std::string& text, int maxWidth, int charWidth)
{
    std::vector<std::string> lines;
    std::istringstream in{ text };
    std::string word, current;
    while (in >> word)
    {
        const std::string candidate{ current.empty() ? word : current + " " + word };
        if (!current.empty() && static_cast<int>(candidate.size()) * charWidth > maxWidth)
        {
            lines.push_back(current);
            current = word;
        }
        else current = candidate;
    }
    if (!current.empty()) lines.push_back(current);
    return lines;
}

class Menu
{
public:
    void add(const std::string& label, bool enabled = true)
    {
        m_items.push_back({ label, enabled });
        if (m_selected < 0 && enabled) m_selected = static_cast<int>(m_items.size()) - 1;
    }

    void move(int delta)
    {
        if (m_selected < 0) return;
        const int n{ static_cast<int>(m_items.size()) };
        int i{ m_selected };
        for (int tries{ 0 }; tries < n; ++tries)
        {
            i = ((i + delta) % n + n) % n;
            if (m_items[static_cast<std::size_t>(i)].enabled) { m_selected = i; return; }
        }
    }

    void hover(int index)
    {
        if (index >= 0 && index < static_cast<int>(m_items.size()) && m_items[static_cast<std::size_t>(index)].enabled) m_selected = index;
    }

    int selected() const { return m_selected; }

    std::string line(int index) const
    {
        const Item& it{ m_items[static_cast<std::size_t>(index)] };
        if (!it.enabled) return "  (" + it.label + ")";
        return (index == m_selected ? "> " : "  ") + it.label;
    }

private:
    struct Item { std::string label; bool enabled; };
    std::vector<Item> m_items;
    int m_selected{ -1 };
};

unitTests:
using Lines = std::vector<std::string>;
TEST("wrapping") {
    CHECK_EQ(wrapText("the quick brown fox jumps", 100, 10), (Lines{ "the quick", "brown fox", "jumps" }));
    CHECK_EQ(wrapText("  spaced    out  ", 1000, 10), (Lines{ "spaced out" }));
    CHECK_EQ(wrapText("a extraordinarily b", 50, 10), (Lines{ "a", "extraordinarily", "b" }));
    CHECK(wrapText("", 100, 10).empty());
}
TEST("menu selection") {
    Menu m; m.add("Continue", false); m.add("New Game"); m.add("Options"); m.add("Quit");
    CHECK_EQ(m.selected(), 1); m.move(1); CHECK_EQ(m.selected(), 2); m.move(1); m.move(1); CHECK_EQ(m.selected(), 1);
    m.move(-1); CHECK_EQ(m.selected(), 3);
    CHECK_EQ(m.line(0), std::string("  (Continue)")); CHECK_EQ(m.line(3), std::string("> Quit")); CHECK_EQ(m.line(1), std::string("  New Game"));
}
TEST("hover") { Menu m; m.add("A"); m.add("B", false); m.add("C"); m.hover(2); CHECK_EQ(m.selected(), 2); m.hover(1); CHECK_EQ(m.selected(), 2); m.hover(9); CHECK_EQ(m.selected(), 2); }
TEST("nothing enabled") { Menu m; m.add("A", false); CHECK_EQ(m.selected(), -1); m.move(1); CHECK_EQ(m.selected(), -1); }

